function resize(){const previousW=W,oldRatio=scale/fitScale,worldX=(W/2-panX)/scale,worldY=(H/2-panY)/scale;W=$('stage').clientWidth;H=$('stage').clientHeight;dpr=Math.min(devicePixelRatio||1,2);for(const a of[c,cloud]){a.width=W*dpr;a.height=H*dpr}ctx.setTransform(dpr,0,0,dpr,0,0);cc.setTransform(dpr,0,0,dpr,0,0);if(previousW){fitScale=Math.min((W-32)/2048,(H-32)/1078);scale=fitScale*oldRatio;panX=W/2-worldX*scale;panY=H/2-worldY*scale;updateMap()}else fitMap()}
